Q: Detect existence of name in at least one base class A: <p>Something tells me this is too convoluted to be included in Chromium, but there's a solution using stateful metaprogramming:</p>
<p><a href="https://gcc.godbolt.org/z/WGjK9496f" rel="nofollow noreferrer"><kbd>run on godbolt</kbd></a></p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;cstddef&gt;
#include &lt;type_traits&gt;
#include &lt;utility&gt;

#if defined(__GNUC__) &amp;&amp; !defined(__clang__)
#define NON_TEMPLATE_FRIEND(...) _Pragma(&quot;GCC diagnostic push&quot;) _Pragma(&quot;GCC diagnostic ignored \&quot;-Wnon-template-friend\&quot;&quot;) __VA_ARGS__ _Pragma(&quot;GCC diagnostic pop&quot;)
#else
#define NON_TEMPLATE_FRIEND(...) __VA_ARGS__
#endif

namespace detail
{
    template &lt;typename T&gt;
    inline constexpr bool always_false = false;

    template &lt;typename T&gt;
    struct SelfTypeReader
    {
        NON_TEMPLATE_FRIEND(
        friend auto adl_GetSelfType(SelfTypeReader&lt;T&gt;);
        )
    };

    template &lt;typename T, typename U&gt;
    struct SelfTypeWriter
    {
        friend auto adl_GetSelfType(SelfTypeReader&lt;T&gt;){return U{};}
    };

    constexpr void adl_GetSelfType() {}

    template &lt;typename T&gt;
    using SelfType = std::remove_pointer_t&lt;decltype(adl_GetSelfType(SelfTypeReader&lt;T&gt;{}))&gt;;

    template &lt;typename T&gt;
    struct FlagReader
    {
        NON_TEMPLATE_FRIEND(
        friend auto adl_ReadFlag(FlagReader&lt;T&gt;);
        )
    };

    template &lt;typename T&gt;
    struct FlagWriter
    {
        friend auto adl_ReadFlag(FlagReader&lt;T&gt;) {}
    };

    constexpr void adl_ReadFlag() {} // Dummy ADL target.

    template &lt;typename T&gt;
    constexpr void adl_SetFlag(void *) {} // ADL target.

    template &lt;typename T, typename = void&gt; constexpr bool has_flag = false;
    template &lt;typename T&gt; constexpr bool has_flag&lt;T, decltype(void(adl_ReadFlag(FlagReader&lt;T&gt;{})))&gt; = true;

    template &lt;typename T&gt;
    constexpr bool has_marker = (adl_SetFlag&lt;T&gt;((T *)nullptr), has_flag&lt;T&gt;);
}

template &lt;typename T&gt;
constexpr bool has_marker = detail::has_marker&lt;T&gt;;

#define INJECT_MARKER \
    struct _self_type_tag {}; \
    constexpr auto _self_type_helper() -&gt; decltype(::detail::SelfTypeWriter&lt;_self_type_tag, decltype(this)&gt;{}, void()) {} \
    template &lt; \
        typename T, \
        std::enable_if_t&lt;std::is_base_of_v&lt;::detail::SelfType&lt;_self_type_tag&gt;, T&gt;, std::nullptr_t&gt; = nullptr, \
        std::enable_if_t&lt;(::detail::FlagWriter&lt;T&gt;{}, false), std::nullptr_t&gt; = nullptr \
    &gt; \
    friend constexpr void adl_SetFlag(void *) {}

// ---

struct A {};
struct B {INJECT_MARKER};
struct C {INJECT_MARKER struct C0 {};};
struct D : B, C {};

static_assert(!has_marker&lt;A&gt;);
static_assert(has_marker&lt;B&gt;);
static_assert(has_marker&lt;C&gt;);
static_assert(!has_marker&lt;C::C0&gt;);
static_assert(has_marker&lt;D&gt;);
</code></pre>
<p>We define a <code>friend</code> function in the macro, and then try to call it.</p>
<p>Since normally that call would be ambiguous if you inherit from several classes that use <code>INJECT_MACRO</code>, we instead intentionally unconditionally disable those <code>friend</code> functions with SFINAE, and provide a fallback function that's always called instead of those.</p>
<p>But we also use stateful metaprogramming to check that those disabled functions were considered during overload resolution, and then if any of them were considered, we know the type has this marker.</p>
<p>This is the same technique as used in <a href="https://stackoverflow.com/a/67793557/2752075">Get base class for a type in class hierarchy</a>, but simpler, since we aren't tring to reconstruct the inheritance hierarchy, and are just checking for presence of at least one marked base.</p>
<p>This also uses the technique from <a href="https://stackoverflow.com/a/70701479/2752075">Can I implement an autonomous <code>self</code> member type in C++?</a> to get the enclosing class type in the macro, without having to pass it to the macro as a parameter.</p>

Q: Laravel catch TokenMismatchException A: <p>This is the only thing I could get working to to pass the message to a page displaying validation errors in Laravel 9.</p>
<pre><code>// Inside app/Exceptions/Handler
$this-&gt;renderable(function (Exception $exception) {
    if ($exception instanceof HttpException) { 
        if ($status === 419) {
            return back()
            -&gt;withErrors(['field' =&gt; 'Session expired for security reasons. Try again.'])
            -&gt;withInput($request-&gt;except('_token'));
        }
    }
});
</code></pre>
<p>Note the <code>field</code> key, which should match the key on the validation errors bag for the Blade view you're redirecting to. For example:</p>
<pre><code>@error(&quot;field&quot;)
  &lt;div&gt;
   &lt;p class=&quot;text-red-500&quot;&gt; {{ $message }} &lt;/p&gt;
  &lt;/div&gt;
@enderror
</code></pre>

