<pre><code>#include &lt;cstddef&gt;
#include &lt;iostream&gt;
#include &lt;typeindex&gt;
#include &lt;utility&gt;

template &lt;typename T&gt;
struct tag
{
    using type = T;
};

template &lt;typename ...P&gt;
struct type_list
{
    inline static constexpr std::size_t size = sizeof...(P);
};

namespace impl
{
    constexpr void adl_ViewBase() {} // A dummy ADL target.

    template &lt;typename D, std::size_t I&gt;
    struct BaseViewer
    {
        #if defined(__GNUC__) &amp;&amp; !defined(__clang__)
        #pragma GCC diagnostic push
        #pragma GCC diagnostic ignored &quot;-Wnon-template-friend&quot;
        #endif
        friend constexpr auto adl_ViewBase(BaseViewer);
        #if defined(__GNUC__) &amp;&amp; !defined(__clang__)
        #pragma GCC diagnostic pop
        #endif
    };

    template &lt;typename D, std::size_t I, typename B&gt;
    struct BaseWriter
    {
        friend constexpr auto adl_ViewBase(BaseViewer&lt;D, I&gt;) {return tag&lt;B&gt;{};}
    };

    template &lt;typename D, typename Unique, std::size_t I = 0, typename = void&gt;
    struct NumBases : std::integral_constant&lt;std::size_t, I&gt; {};

    template &lt;typename D, typename Unique, std::size_t I&gt;
    struct NumBases&lt;D, Unique, I, decltype(adl_ViewBase(BaseViewer&lt;D, I&gt;{}), void())&gt; : std::integral_constant&lt;std::size_t, NumBases&lt;D, Unique, I+1, void&gt;::value&gt; {};

    template &lt;typename D, typename B&gt;
    struct BaseInserter : BaseWriter&lt;D, NumBases&lt;D, B&gt;::value, B&gt; {};

    template &lt;typename T&gt;
    constexpr void adl_RegisterBases(void *) {} // A dummy ADL target.

    template &lt;typename T&gt;
    struct RegisterBases : decltype(adl_RegisterBases&lt;T&gt;((T *)nullptr), tag&lt;void&gt;())
    {};

    template &lt;typename T, typename I&gt;
    struct BaseListLow {};

    template &lt;typename T, std::size_t ...I&gt;
    struct BaseListLow&lt;T, std::index_sequence&lt;I...&gt;&gt;
    {
        static constexpr type_list&lt;decltype(adl_ViewBase(BaseViewer&lt;T, I&gt;{}))...&gt; helper() {}
        using type = decltype(helper());
    };

    template &lt;typename T&gt;
    struct BaseList : BaseListLow&lt;T, std::make_index_sequence&lt;(impl::RegisterBases&lt;T&gt;{}, NumBases&lt;T, void&gt;::value)&gt;&gt; {};
}

template &lt;typename T&gt;
using base_list = typename impl::BaseList&lt;T&gt;::type;

template &lt;typename T&gt;
struct Base
{
    template &lt;
        typename D,
        std::enable_if_t&lt;std::is_base_of_v&lt;T, D&gt;, std::nullptr_t&gt; = nullptr,
        typename impl::BaseInserter&lt;D, T&gt;::nonExistent = nullptr
    &gt;
    friend constexpr void adl_RegisterBases(void *) {}
};


struct A : Base&lt;A&gt; {};
struct B : Base&lt;B&gt;, A {};
struct C : Base&lt;C&gt; {};
struct D : Base&lt;D&gt;, B, C {};

template &lt;typename T&gt;
void printType()
{
    #ifndef _MSC_VER
    std::cout &lt;&lt; __PRETTY_FUNCTION__ &lt;&lt; '\n';
    #else
    std::cout &lt;&lt; __FUNCSIG__ &lt;&lt; '\n';
    #endif
};

int main()
{
    static_assert( base_list&lt;D&gt;::size == 4 );
    printType&lt;base_list&lt;D&gt;&gt;(); // typeList&lt;tag&lt;A&gt;, tag&lt;B&gt;, tag&lt;C&gt;, tag&lt;D&gt;&gt;, order may vary
}
</code></pre>
<p>Here's what's going on:</p>
<ul>
<li>You use stateful template metaprogramming to create a list of types, which you can append types to by instantiating a specific template.</li>
<li>Using a CRTP base, you add a <code>friend</code> function to each class that needs to be detectable in this manner. Those functions are made uncallable with SFINAE, but merely <strong>considering</strong> them during overload resolution instantiates the template that appends the corresponding base class to the list.</li>
<li>You invoke this overloaded function with ADL, and since overloads from all bases are considered and are attempted to be instantiated, you get a list of bases.</li>
</ul>
<p>Note that you can combine this with <a href="https://stackoverflow.com/a/70701479/2752075">Can I implement an autonomous <code>self</code> member type in C++?</a> to instead mark the bases with a macro, and not have to spell the base type twice.</p>
